const createEvents = (
  openEntireDay: boolean,
  events: {
    startDateAndTime: string;
    endDateAndTime: string;
  }[],
) => {
  const eventArray: Array<ContentfulEvent> = [];

  for (const event of events) {
    const startDate = dayjs(event.startDateAndTime);
    const endDate = dayjs(event.endDateAndTime);

    eventArray.push({
      id: `period-4Y6aopvWEEIv6BE9VB0Uf6-${startDate.toString()}`,
      title: `Circusrestaurangen - Sommar (B4K) #${startDate.toString() + 1}`,
      startDateAndTime: openEntireDay ? startDate.set("hour", 9).toString() : startDate.toString(),
      endDateAndTime: !openEntireDay
        ? undefined
        : openEntireDay
        ? endDate.set("hour", 20).toString()
        : endDate.toString(),
      startDateAndTimeWithTimeZone: startDate.toString(),
      endDateAndTimeWithTimeZone: endDate.toString(),
      description: "",
      externalEntry: {
        externalEntryId: `3jpTHTtjfEb0LSkQTM9Ba6-${startDate.toString()}`,
      },
      cancelled: false,
      cancelledText: "",
    });
  }
  return eventArray.sort((a, b) => {
    return dayjs(a.startDateAndTime).isBefore(dayjs(b.startDateAndTime)) ? -1 : 1;
  });
};
