const getCancelledEventsByActivity = (events: Array<ContentfulEvent>) => {
  return events.map((event, index) => {
    return {
      ...event,
      cancelled: index === 0,
      cancelledText: index === 0 ? "Stängd denna dag" : "",
    };
  });
};

const getPassedEventsByActivity = (events: Array<ContentfulEvent>) => {
  return events.map((event, index) => {
    const date = dayjs(event.startDateAndTime);

    return {
      ...event,
      startDateAndTime:
        index === 0
          ? date.set("hour", 3).set("minute", 0).toString()
          : index === 1
          ? date.set("hour", 3).set("minute", 0).toString()
          : event.startDateAndTime,
      endDateAndTime:
        index === 0 ? undefined : index === 1 ? date.set("hour", 22).set("minute", 0).toString() : event.endDateAndTime,
    };
  });
};

